    function bindEvents() {
      const trigger = document.querySelector(".trigger");
      const dialog = document.getElementById("delete-dialog");
      const closeButton = dialog.querySelector("[data-close]");
      const confirmButton = dialog.querySelector("[data-confirm]");

      if (trigger) {
