const fs = require('fs');
const { chromium } = require('playwright');
const axeSource = require('axe-core').source;
(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  let browser;
  try {
    browser = await chromium.launch();
  } catch (error) {
    console.log('PLAYWRIGHT_LAUNCH_FAIL');
    console.log(String(error.message || error));
    process.exit(2);
  }
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axeSource });
  const summarize = async () => {
    const results = await page.evaluate(async () => {
      const r = await window.axe.run();
      return r.violations.map(v => ({
        id: v.id,
        impact: v.impact,
        tags: v.tags,
        targets: v.nodes.map(n => n.target)
      }));
    });
    return {
      all: results,
      wcag: results.filter(v => !v.tags.includes('best-practice'))
    };
  };
  const defaultState = await summarize();
  await page.click('.trigger');
  const dialogState = await summarize();
  await browser.close();
  const output = { default: defaultState, dialog: dialogState };
  console.log(JSON.stringify(output, null, 2));
  process.exit(defaultState.wcag.length || dialogState.wcag.length ? 1 : 0);
})();
